	(272, 3, 1, 'update', 'risk', 797, '"\"{\\\"title\\\":\\\"ML05:2023: Model Theft on AI Financial Advisor\\\",\\\"changes\\\":{\\\"clientId\\\":3,\\\"title\\\":\\\"ML05:2023: Model Theft on AI Financial Advisor\\\",\\\"likelihood\\\":\\\"4\\\",\\\"impact\\\":\\\"4\\\",\\\"inherentScore\\\":16,\\\"inherentRisk\\\":\\\"Very High\\\",\\\"status\\\":\\\"approved\\\",\\\"riskOwner\\\":\\\"\\\",\\\"threatDescription\\\":\\\"Duplicating or extracting a model by querying it and using the responses to train a competitor''s ''substitute'' model. (Context: ML05:2023 - AI Agent)\\\",\\\"method\\\":\\\"NIST SP 800-30\\\",\\\"vulnerabilityDescription\\\":\\\"\\\",\\\"recommendedActions\\\":\\\"\\\",\\\"updatedAt\\\":\\\"2026-02-14T23:48:17.822Z\\\"}}\""', 'info', NULL, NULL, '2026-02-14 23:48:18.933114'),
