INSERT INTO public.bc_strategies VALUES
	(73, 3, 'Active-Active Geo-Replication', 'Real-time replication of all transaction databases to the secondary region (us-west-2). Enables sub-minute RPO and RTO < 15 mins.', 'Requires updated contact list and active VPN tokens.', '$50k/mo', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.170952'),
	(74, 3, 'Cold Storage Restore', 'Daily snapshots sent to S3 Glacier Vault (Immutable). Use for ransomware recovery where data integrity is compromised.', 'Requires updated contact list and active VPN tokens.', '$5k/mo', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.279071'),
	(75, 3, 'Remote Work Activation (WFH)', 'All employees issued corporate laptops with VPN. Dept heads trigger call-tree to instruct staff to work from home.', 'Requires updated contact list and active VPN tokens.', '$0', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.387474'),
	(76, 3, 'Manual Payment Processing', 'Fallback paper-based forms for high-value transactions. Strictly limited to <$100k amounts until systems restored.', 'Requires updated contact list and active VPN tokens.', 'High Effort', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.496481'),
	(77, 3, 'Vendor Failover (Secondary Provider)', 'Contract in place with ''BackupPay Ltd'' to route traffic if primary gateway fails. Requires DNS switch.', 'Requires updated contact list and active VPN tokens.', 'Variable', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.604523'),
	(78, 3, 'Crisis Communcation Protocol', 'Pre-drafted templates for Twitter/X, Email, and SMS. PR Firm on retainer to handle media inquiries.', 'Requires updated contact list and active VPN tokens.', '$10k retainer', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.7138'),
	(79, 3, 'Emergency Hiring / Staffing Agency', 'On-demand contract with ''TechStaffing'' to supply 20 additional support agents within 24 hours.', 'Requires updated contact list and active VPN tokens.', 'Market Rate', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.821505'),
	(80, 3, 'Cyber Incident Response Team (CIRT)', 'Retainer with ''SecureDefend''. 1-hour SLA for on-site (virtual) forensic analysis and containment.', 'Requires updated contact list and active VPN tokens.', '$20k retainer', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:04.931493'),
	(81, 3, 'Alternate Office Site (WeWork)', 'Membership for 50 hot-desks at WeWork downtown. Use for critical ops staff if HQ is inaccessible.', 'Requires updated contact list and active VPN tokens.', '$5k/mo', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:05.046023'),
	(82, 3, 'Paper-based Operations', 'General fallback for non-critical admin tasks. Logs kept manually and entered when systems return.', 'Requires updated contact list and active VPN tokens.', 'Low', 'Ensures continuity of operations within defined RTOs.', 'approved', '2026-01-07 16:01:05.156019');
