	(9, 'OWASP SAMM (Maturity Model)', 'SAMM', '2.0', 'OWASP Software Assurance Maturity Model. Governance and maturity measurement.', 'framework', '2026-02-05 00:26:55.540041', '2026-02-05 00:26:55.540041'),
	(10, 'OWASP API Security Top 10', 'API-T10', '2023', 'The most critical API security risks.', 'framework', '2026-02-05 00:27:00.203695', '2026-02-05 00:27:00.203695'),
	(11, 'OWASP Web Top 10', 'WEB-T10', '2021', 'The standard awareness document for developers and web application security.', 'framework', '2026-02-05 00:27:02.884768', '2026-02-05 00:27:02.884768'),
	(12, 'OWASP Web Top 10', 'owasp_top10', '2025', 'OWASP Web Top 10 2025', 'Security', '2026-02-05 07:05:06.35374', '2026-02-05 07:05:06.35374'),
