INSERT INTO public.control_tech_mappings VALUES
	(1, 'A.5.1', 'ISO 27001:2022', 'policy-management-reciprocity', 'Reciprocity', 'ZenGRC', 'Governance, risk, and compliance platform with policy management, version control, and attestation workflows', '"[\"Built-in policy templates for ISO 27001, SOC 2, GDPR\",\"Automated policy review cycles and approvals\",\"Integration with ticketing systems\"]"', '"[\"Can be expensive for small teams\",\"Requires training for full utilization\"]"', 'medium', 'mature', '"[{\"url\":\"https://reciprocity.com/platform/policy-management/\",\"title\":\"Reciprocity Policy Management\"}]"', '2026-01-01 18:57:09.126172', '2026-01-01 18:57:09.126172'),
	(2, 'A.5.1', 'ISO 27001:2022', 'policy-management-drata', 'Drata', 'Compliance Automation Platform', 'Automates compliance monitoring with policy management and continuous evidence collection', '"[\"Easy onboarding\",\"Automated evidence collection\",\"Real-time compliance monitoring\"]"', '"[\"Limited customization for unique policies\",\"Premium pricing\"]"', 'low', 'mature', '"[{\"url\":\"https://drata.com/features/policy-management\",\"title\":\"Drata Policy Management\"}]"', '2026-01-01 18:57:09.969807', '2026-01-01 18:57:09.969807'),
	(3, 'A.8.1', 'ISO 27001:2022', 'asset-discovery-servicenow', 'ServiceNow', 'IT Asset Management (ITAM)', 'Enterprise asset management with auto-discovery, lifecycle tracking, and financial management', '"[\"Comprehensive asset tracking across hardware, software, cloud\",\"Strong integration ecosystem\",\"Scalable for large organizations\"]"', '"[\"High cost and complexity\",\"Steep learning curve\"]"', 'high', 'mature', '"[{\"url\":\"https://www.servicenow.com/products/it-asset-management.html\",\"title\":\"ServiceNow ITAM\"}]"', '2026-01-01 18:57:10.873398', '2026-01-01 18:57:10.873398'),
	(4, 'A.8.1', 'ISO 27001:2022', 'asset-discovery-snipeit', 'Open Source', 'Snipe-IT', 'Free, open-source IT asset management with barcode scanning, check-in/check-out, and custom fields', '"[\"Free and open-source\",\"Easy to deploy (Docker available)\",\"Active community support\"]"', '"[\"Manual setup required\",\"Limited auto-discovery vs commercial tools\"]"', 'low', 'mature', '"[{\"url\":\"https://snipeitapp.com/\",\"title\":\"Snipe-IT Homepage\"}]"', '2026-01-01 18:57:11.785643', '2026-01-01 18:57:11.785643'),
	(5, 'A.9.2', 'ISO 27001:2022', 'iam-okta', 'Okta', 'Okta Identity Cloud', 'Cloud-native IAM with SSO, MFA, and lifecycle management for 7000+ integrations', '"[\"Extensive app catalog (7000+ pre-built integrations)\",\"Strong MFA options (push, SMS, TOTP, WebAuthn)\",\"Excellent user experience\",\"Automated provisioning/deprovisioning\"]"', '"[\"Premium features require higher tiers\",\"Complex policy configuration for advanced use cases\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.okta.com/resources/whitepaper/okta-iso-27001-guide/\",\"title\":\"Okta ISO 27001 Guide\"}]"', '2026-01-01 18:57:12.641346', '2026-01-01 18:57:12.641346'),
	(6, 'A.9.2', 'ISO 27001:2022', 'iam-azure-ad', 'Microsoft', 'Azure Active Directory / Entra ID', 'Cloud IAM with deep Microsoft 365 integration and conditional access policies', '"[\"Deep integration with M365 and Azure ecosystem\",\"Conditional access and risk-based authentication\",\"Included in many Microsoft licensing bundles\"]"', '"[\"Licensing complexity (P1/P2 features)\",\"Best for Microsoft-centric environments\"]"', 'low', 'mature', '"[{\"url\":\"https://learn.microsoft.com/en-us/azure/active-directory/\",\"title\":\"Azure AD Documentation\"}]"', '2026-01-01 18:57:13.544432', '2026-01-01 18:57:13.544432'),
	(7, 'A.9.2', 'ISO 27001:2022', 'iam-auth0', 'Auth0 (Okta)', 'Auth0 Identity Platform', 'Developer-friendly IAM with customizable login flows and extensive SDK support', '"[\"Easy integration for custom applications\",\"Flexible authentication flows\",\"Strong developer documentation\"]"', '"[\"Can get expensive with high MAU\",\"Enterprise features require higher plans\"]"', 'medium', 'mature', '"[{\"url\":\"https://auth0.com/docs/get-started/identity-fundamentals\",\"title\":\"Auth0 Documentation\"}]"', '2026-01-01 18:57:14.391988', '2026-01-01 18:57:14.391988'),
	(8, 'A.12.3', 'ISO 27001:2022', 'backup-veeam', 'Veeam', 'Veeam Backup & Replication', 'Enterprise backup solution for virtual, physical, and cloud workloads with immutable backups', '"[\"Supports wide range of platforms (VMware, Hyper-V, cloud)\",\"Immutable backup for ransomware protection\",\"Fast recovery with Instant VM Recovery\"]"', '"[\"Licensing costs can be high\",\"Requires dedicated infrastructure\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.veeam.com/products/veeam-data-platform.html\",\"title\":\"Veeam Backup & Replication\"}]"', '2026-01-01 18:57:15.253015', '2026-01-01 18:57:15.253015'),
	(9, 'A.12.3', 'ISO 27001:2022', 'backup-aws-backup', 'AWS', 'AWS Backup', 'Centralized backup service for AWS resources with policy-based automation', '"[\"Native integration with AWS services\",\"Cross-region and cross-account backups\",\"Compliance-ready vault lock\"]"', '"[\"AWS-only (doesn''t backup on-prem or other clouds natively)\",\"Pricing can add up for large volumes\"]"', 'low', 'mature', '"[{\"url\":\"https://aws.amazon.com/backup/\",\"title\":\"AWS Backup\"}]"', '2026-01-01 18:57:16.231919', '2026-01-01 18:57:16.231919'),
	(10, 'A.14.2', 'ISO 27001:2022', 'devsecops-github-actions', 'GitHub', 'GitHub Advanced Security + Actions', 'Integrated CI/CD with code scanning, secret scanning, and dependency review', '"[\"Integrated into developer workflow\",\"Automated security scanning in pull requests\",\"Broad language support\"]"', '"[\"Requires GitHub Enterprise for private repos\",\"Can have false positives requiring tuning\"]"', 'low', 'mature', '"[{\"url\":\"https://docs.github.com/en/code-security\",\"title\":\"GitHub Advanced Security\"}]"', '2026-01-01 18:57:17.173119', '2026-01-01 18:57:17.173119'),
	(11, 'A.14.2', 'ISO 27001:2022', 'devsecops-snyk', 'Snyk', 'Snyk Security Platform', 'Developer-first security with vulnerability scanning for code, containers, IaC, and open-source dependencies', '"[\"Very developer-friendly UI and IDE integrations\",\"Excellent open-source vulnerability database\",\"Actionable fix recommendations\"]"', '"[\"Can be costly for large organizations\",\"May overwhelm teams with alerts initially\"]"', 'low', 'mature', '"[{\"url\":\"https://snyk.io/product/\",\"title\":\"Snyk Platform\"}]"', '2026-01-01 18:57:18.28944', '2026-01-01 18:57:18.28944'),
	(12, 'A.16.1', 'ISO 27001:2022', 'incident-pagerduty', 'PagerDuty', 'PagerDuty Incident Response', 'Incident response platform with on-call management, escalation, and postmortem workflows', '"[\"Excellent on-call scheduling and rotations\",\"Broad integration with monitoring tools\",\"Structured incident response workflows\"]"', '"[\"Can be expensive for large teams\",\"Requires process discipline to be effective\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.pagerduty.com/platform/incident-response/\",\"title\":\"PagerDuty Incident Response\"}]"', '2026-01-01 18:57:19.183966', '2026-01-01 18:57:19.183966'),
	(13, 'A.16.1', 'ISO 27001:2022', 'incident-jira-service-desk', 'Atlassian', 'Jira Service Management', 'ITSM platform with incident management, problem tracking, and change management', '"[\"Integrates with Jira Software for development tracking\",\"Customizable workflows\",\"Strong reporting and analytics\"]"', '"[\"Can be complex to configure\",\"Performance issues with very large instances\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.atlassian.com/software/jira/service-management\",\"title\":\"Jira Service Management\"}]"', '2026-01-01 18:57:20.133009', '2026-01-01 18:57:20.133009'),
	(14, 'A.17.1', 'ISO 27001:2022', 'dr-zerto', 'Zerto (HP)', 'Zerto Disaster Recovery', 'Continuous data protection and disaster recovery for VMs and cloud workloads', '"[\"Near-zero RPO with continuous replication\",\"Automated failover and failback\",\"Non-disruptive testing\"]"', '"[\"Enterprise pricing\",\"Complexity in multi-cloud scenarios\"]"', 'high', 'mature', '"[{\"url\":\"https://www.zerto.com/\",\"title\":\"Zerto Platform\"}]"', '2026-01-01 18:57:20.997285', '2026-01-01 18:57:20.997285'),
	(15, 'A.18.1', 'ISO 27001:2022', 'compliance-vanta', 'Vanta', 'Vanta Automation Platform', 'Automated compliance for SOC 2, ISO 27001, GDPR with continuous monitoring', '"[\"Fast time to certification\",\"Automates evidence collection\",\"User-friendly interface\"]"', '"[\"Can be expensive\",\"Less flexibility for custom frameworks\"]"', 'low', 'mature', '"[{\"url\":\"https://www.vanta.com/\",\"title\":\"Vanta Platform\"}]"', '2026-01-01 18:57:22.003552', '2026-01-01 18:57:22.003552'),
	(16, 'A.18.1', 'ISO 27001:2022', 'compliance-secureframe', 'Secureframe', 'Compliance Automation', 'Automated compliance platform with AI-powered evidence collection and streamlined auditor collaboration', '"[\"Strong auditor collaboration features\",\"Automated evidence collection from 100+ integrations\",\"Good customer support\"]"', '"[\"Premium pricing\",\"Limited customization for niche requirements\"]"', 'low', 'mature', '"[{\"url\":\"https://secureframe.com/\",\"title\":\"Secureframe Platform\"}]"', '2026-01-01 18:57:22.988975', '2026-01-01 18:57:22.988975');
