INSERT INTO public.vendors VALUES
	(72, 679, '11x', NULL, 'https://www.11x.ai/', 'Medium', 'Internal', NULL, 'Active', NULL, '2026-01-20 23:03:19.23', '2026-01-20 23:03:07.414504', NULL, 'SaaS', 'Global Catalog', '2026-01-20 23:03:07.236', 'active', 'https://trust.delve.co/11x', '"{\"score\":50,\"docs\":[{\"name\":\"11x Trust Center (Delve)\",\"url\":\"https://trust.delve.co/11x\",\"type\":\"Trust Center\"}],\"gaps\":[\"Unable to verify (from provided sources in this run) whether 11x holds SOC 2 Type II, ISO 27001, or other common certifications; no directly linkable certification reports were confirmed here\",\"No publicly confirmed GDPR Article 28-ready DPA terms (controller-processor clauses) were found/verified here (e.g., processing instructions, confidentiality, security measures, subprocessors, assistance, deletion/return, audits)\",\"No publicly confirmed subprocessor list was found/verified here (names, purposes, locations, change-notification mechanism)\",\"No publicly confirmed breach notification window was found/verified (e.g., ''without undue delay'' / specific hours)\",\"No publicly confirmed audit rights language was found/verified (e.g., third-party audit reports, on-site audits, frequency, notice, cost allocation)\",\"No publicly confirmed liability cap language was found/verified (cap basis, carve-outs, data protection-specific caps)\",\"No publicly confirmed international transfer mechanism was found/verified (SCCs/UK IDTA, transfer impact assessments, onward transfer controls)\"],\"riskSummary\":\"Based on the publicly provided Trust Center URL and website alone (without verifiable access to specific downloadable compliance artifacts in this run), GDPR Article 28 suitability cannot be confirmed. The key GDPR processor requirements typically evidenced via a Data Processing Agreement (DPA)—including defined breach notice timing, clear audit/inspection rights, a maintained subprocessor register with change notification, and explicit liability/cap structure—were not verifiably available here. This creates elevated contracting and compliance risk for a controller relying on 11x as a processor, especially if personal data, special category data, or EU/UK-to-third-country transfers are involved. Proceed would likely require obtaining and reviewing an executed DPA (including SCCs/UK IDTA if relevant), current subprocessor list, and independent assurance (e.g., SOC 2 Type II/ISO 27001) before onboarding.\",\"subprocessors\":[],\"dpaAnalysis\":{\"liabilityCap\":\"Unknown (not publicly verified from provided sources in this run)\",\"auditRights\":\"Unknown (not publicly verified from provided sources in this run)\",\"breachNoticeWindow\":\"Unknown (not publicly verified from provided sources in this run)\"}}"', 50, NULL, NULL, NULL, true, 'Global', NULL, '"[]"', '"{\"liabilityCap\":\"Unknown (not publicly verified from provided sources in this run)\",\"auditRights\":\"Unknown (not publicly verified from provided sources in this run)\",\"breachNoticeWindow\":\"Unknown (not publicly verified from provided sources in this run)\"}"', NULL, false, false, NULL, NULL, false, 1, NULL),
	(73, 679, 'Abacum', NULL, 'https://www.abacum.ai/', 'Medium', 'Internal', NULL, 'Active', NULL, '2026-01-20 23:03:25.385', '2026-01-20 23:03:13.843506', NULL, 'SaaS', 'Global Catalog', '2026-01-20 23:03:13.668', 'active', 'https://trust.abacum.ai', '"{\"score\":50,\"docs\":[{\"name\":\"Abacum Trust Center\",\"url\":\"https://trust.abacum.ai\",\"type\":\"Trust Center\"}],\"gaps\":[\"Unable to verify (from provided information alone) whether Abacum holds SOC 2 Type II, ISO 27001, or other common third-party security certifications\",\"No publicly verifiable GDPR Article 28 DPA terms found in the provided inputs (e.g., DPA link, processing terms, SCCs/UK IDTA addendum)\",\"No publicly verifiable subprocessor list identified from the provided inputs\",\"No publicly verifiable breach notification window (e.g., 72 hours) identified from the provided inputs\",\"No publicly verifiable audit rights language (e.g., on-site vs. third-party report substitution, frequency, notice period) identified from the provided inputs\",\"No publicly verifiable liability cap language (e.g., 12 months fees, uncapped for data protection breaches) identified from the provided inputs\",\"No publicly verifiable information on international transfer mechanism (SCCs, transfer impact assessments, data residency) identified from the provided inputs\",\"No publicly verifiable retention/deletion commitments and assistance obligations (Art. 28(3)(g)-(h)) identified from the provided inputs\"],\"riskSummary\":\"From the provided sources, Abacum appears to operate a Trust Center, but key GDPR Article 28 processor obligations cannot be confirmed without access to the DPA/processing terms and a public subprocessor list. This creates elevated uncertainty for GDPR suitability: you cannot currently validate required Art. 28(3) clauses (documented instructions, confidentiality, security measures, subprocessor authorization/flow-down, assistance with data subject rights, breach support, deletion/return, and audit/inspection rights). Proceeding would require obtaining and reviewing the executed DPA (including SCCs/UK addendum if applicable), confirming breach notification SLA, audit mechanism, liability allocation, and the complete subprocessor register with locations and transfer safeguards.\",\"subprocessors\":[],\"dpaAnalysis\":{\"liabilityCap\":\"Unknown (not publicly verifiable from provided inputs)\",\"auditRights\":\"Unknown (not publicly verifiable from provided inputs)\",\"breachNoticeWindow\":\"Unknown (not publicly verifiable from provided inputs)\"}}"', 50, NULL, NULL, NULL, true, 'Global', NULL, '"[]"', '"{\"liabilityCap\":\"Unknown (not publicly verifiable from provided inputs)\",\"auditRights\":\"Unknown (not publicly verifiable from provided inputs)\",\"breachNoticeWindow\":\"Unknown (not publicly verifiable from provided inputs)\"}"', NULL, false, false, NULL, NULL, false, 1, NULL),
	(74, 679, '1Password', NULL, 'https://1password.com/', 'Medium', 'Internal', NULL, 'Active', NULL, '2026-01-20 23:03:34.094', '2026-01-20 23:03:17.267808', NULL, 'SaaS', 'Global Catalog', '2026-01-20 23:03:17.092', 'active', 'https://app.conveyor.com/profile/1password', '"{\"score\":82,\"docs\":[{\"name\":\"1Password Trust Center (security & compliance portal)\",\"url\":\"https://app.conveyor.com/profile/1password\",\"type\":\"TrustCenter\"},{\"name\":\"SOC 2 Type II (availability/security/confidentiality) (likely available via Trust Center under NDA)\",\"url\":\"https://app.conveyor.com/profile/1password\",\"type\":\"SOC2\"},{\"name\":\"ISO/IEC 27001 (likely available via Trust Center)\",\"url\":\"https://app.conveyor.com/profile/1password\",\"type\":\"ISO27001\"},{\"name\":\"Data Processing Addendum (DPA) / GDPR terms (likely available via Trust Center or legal page)\",\"url\":\"https://1password.com/\",\"type\":\"DPA\"}],\"gaps\":[\"Could not verify specific certifications and report scope publicly from the provided URLs without access to gated Trust Center artifacts (e.g., SOC 2 report PDF, ISO certificate).\",\"Could not confirm whether a public SOC 3 report is available.\",\"Could not confirm the exact GDPR Article 28(3) DPA clauses (audit mechanism, breach notification window, liability cap) because the DPA text was not provided in the prompt and may be gated.\",\"Could not confirm the vendor’s current public subprocessor list and details (names/locations/purposes) from the provided URLs without access to the specific subprocessor page/document.\"],\"riskSummary\":\"1Password generally presents as a mature security vendor (password management) and operates a dedicated Trust Center, which is a positive indicator for GDPR Article 28 readiness (availability of DPAs, security documentation, and compliance artifacts). However, for GDPR Article 28 compliance you should treat this as ''provisionally suitable'' until you obtain and review: (1) the executed DPA with 